import json
from typing import Any, Dict

def _offers_of(obj):
    if not isinstance(obj, dict):
        return []
    offers = obj.get('offers')
    if isinstance(offers, list):
        out = []
        for i, o in enumerate(offers, start=1):
            if not isinstance(o, dict):
                continue
            e = dict(o)
            e.setdefault('offer_seq', i)
            out.append(e)
        return out
    return [obj]

def _join(v):
    if isinstance(v, list):
        return ','.join(str(x) for x in v if str(x))
    return str(v or '')

async def main(args):
    raw = args.params['query_list']
    if not isinstance(raw, str):
        raw = json.dumps(raw, ensure_ascii=False)
    record_json = ''
    offer_id = ''
    global_id = ''
    try:
        arr = json.loads(raw)
        if isinstance(arr, list) and arr:
            first = arr[0]
            if isinstance(first, dict):
                record_json = str(first.get('result_json') or '')
        elif isinstance(arr, dict):
            record_json = str(arr.get('result_json') or '')
    except Exception:
        record_json = ''
    if not record_json:
        record_json = raw
    try:
        inner = json.loads(record_json)
        if isinstance(inner, dict):
            offers = _offers_of(inner)
            if offers:
                offer_id = str(offers[0].get('offer_id') or offers[0].get('offerId') or '')
            ids = []
            normalized = []
            for o in offers:
                gid = _join(o.get('globalId') or o.get('global_id') or '')
                oid = str(o.get('offer_id') or o.get('offerId') or '')
                if gid:
                    ids += [x for x in gid.split(',') if x]
                normalized.append({'offer_seq': o.get('offer_seq'),
                                   'offer_id': oid, 'globalId': gid})
            if not ids:
                ids = [x for x in _join(inner.get('globalId') or inner.get('global_id') or '').split(',') if x]
            global_id = ','.join(ids)
            offers_json = json.dumps(normalized, ensure_ascii=False)
        else:
            offers_json = '[]'
    except Exception:
        offer_id = ''
        global_id = ''
        offers_json = '[]'
    ret: Output = {
        "record_json": record_json,
        "offer_id": offer_id,
        "globalId": global_id,
        "offers": offers_json
    }
    return ret

import json
import asyncio
import urllib.request
from typing import Any, Dict

PROGRESS_URL = 'http://10.86.13.201:31281/api/v1/appstore/test/offer/progress'
INTERVAL = 5
MAX_RETRY = 60
MAX_CONSECUTIVE_FAIL = 5

def _load(v):
    if isinstance(v, list):
        return v
    if isinstance(v, dict):
        return [v]
    if not isinstance(v, str) or not v.strip():
        return []
    try:
        obj = json.loads(v)
        if isinstance(obj, dict) and isinstance(obj.get('offers'), list):
            return obj['offers']
        return obj if isinstance(obj, list) else ([obj] if isinstance(obj, dict) else [])
    except Exception:
        return []

def _poll_round(offers):
    # 鎻愪氦鎵归噺杩涘害绔偣锛岃繑鍥?(ok, all_done, any_failed, fail_reason, per_offer)
    try:
        body = json.dumps({'offers': offers}).encode('utf-8')
        req = urllib.request.Request(PROGRESS_URL, data=body,
                                     headers={'Content-Type': 'application/json'})
        with urllib.request.urlopen(req, timeout=30) as http_resp:
            resp = json.loads(http_resp.read().decode('utf-8'))
    except Exception:
        return False, False, False, '', []
    if not isinstance(resp, dict):
        return False, False, False, '', []
    items = resp.get('offers') or []
    all_done = True
    any_failed = False
    reason = ''
    for it in items:
        if str(it.get('failed', '')).lower() == 'true':
            any_failed = True
            reason = '娴嬭瘯澶辫触/涓锛屼粛鍙栧畬鏁寸粨鏋滀緵鎶ュ憡瀹氫綅澶辫触鍘熷洜'
        if str(it.get('done', '')).lower() != 'true':
            all_done = False
    if not items:
        all_done = False
    return True, all_done, any_failed, reason, items

async def main(args):
    offers = _load(args.params.get('offers'))
    offers = [o for o in offers if isinstance(o, dict) and str(o.get('globalId') or '')]
    if not offers:
        ret: Output = {'done': 'false', 'failed': 'true', 'failIndex': '-1',
                       'fail_reason': '缂哄皯娴嬭瘯娴佹按鍙?globalId锛岃鍏堝彂璧锋祴璇?, 'offers': '[]'}
        return ret
    consecutive_fail = 0
    for i in range(MAX_RETRY):
        ok, all_done, any_failed, reason, items = _poll_round(offers)
        if not ok:
            consecutive_fail += 1
            if consecutive_fail >= MAX_CONSECUTIVE_FAIL:
                ret: Output = {'done': 'false', 'failed': 'true', 'failIndex': '-1',
                               'fail_reason': '杩炵画鏌ヨ澶辫触5娆★紝杞汉宸?, 'offers': '[]'}
                return ret
            await asyncio.sleep(INTERVAL)
            continue
        consecutive_fail = 0
        if any_failed:
            ret: Output = {'done': 'false', 'failed': 'true', 'failIndex': '-1',
                           'fail_reason': reason,
                           'offers': json.dumps(items, ensure_ascii=False)}
            return ret
        if all_done:
            ret: Output = {'done': 'true', 'failed': 'false', 'failIndex': '-1', 'fail_reason': '',
                           'offers': json.dumps(items, ensure_ascii=False)}
            return ret
        await asyncio.sleep(INTERVAL)
    ret: Output = {'done': 'false', 'failed': 'true', 'failIndex': '-1',
                   'fail_reason': '娴嬭瘯澶勭悊涓紝璇风◢鍚庡洖澶嶃€愭煡璇㈡祴璇曠粨鏋溿€戠画鏌?, 'offers': '[]'}
    return ret

